import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { LoadingService } from 'src/app/services/tnvn/services/loading.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-school-inspection',
  templateUrl: './school-inspection.page.html',
  styleUrls: ['./school-inspection.page.scss'],
})
export class SchoolInspectionPage implements OnInit {

  form: FormGroup;
  schoolInfo: any;
  noData: boolean = true;
  submitted: boolean = false;
  routeData: any;
  Id: any;
  noDataFound: boolean;
  username: any;
  data: any;
  udiseLen: any;
  schoolId: any;
  schoolName: any;
  district: any;
  block: any;
  udise: any;
  sessionUserName: any;
  filter: any[] = [];
  UdiseCode: any;

  constructor(private fb: FormBuilder, private userService: UserService, private route: ActivatedRoute,
    private router: Router, private alertService: AlertService, private userSessionService: UserSessionService,
   ) {
    this.username = this.userSessionService.emis_username();
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.sessionUserName = this.userSessionService.emis_username();
    this.routeData = this.route.snapshot;
    this.UdiseCode = this.routeData.queryParams.uidse; 
    console.log(this.UdiseCode)
    // this.getSchoolInfo()
 }

  getSchoolInfo() {
      this.userService.getSchoolInfo(this.UdiseCode).subscribe((res) => {
        console.log(res,"info")
        if (res.dataStatus) {
          this.noData = false;
          this.noDataFound = false;
          this.schoolInfo = res.result;
          console.log(this.schoolInfo,"info")
        } else {
          this.noData = true;
          this.noDataFound = true;
        }
      });
  }

  goToBack() {
    this.router.navigate(['/tabs/dashboard']);
  }

  onKeypressEvent(event) {
    //debugger
    this.udiseLen = this.UdiseCode;
    let len = this.udiseLen.length;
    if (len == 11) {
    }
    else {
      this.schoolInfo = [];
      this.noData = true;
    }
  }

  nextPage() {
    this.router.navigate(['/tabs/inspection']);
  }

}